import org.spongepowered.asm.mixin.injection.*;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(ItemStackRenderState.class)
public abstract class TridentItemSubmitAuditMixin {
 private static final java.util.ArrayDeque<Boolean> PREVIOUS=new java.util.ArrayDeque<>(),JUMP_PREVIOUS=new java.util.ArrayDeque<>(),SPEAR_PREVIOUS=new java.util.ArrayDeque<>(),MACE_PREVIOUS=new java.util.ArrayDeque<>(),CROSSBOW_PREVIOUS=new java.util.ArrayDeque<>(),GROUND_TRIDENT_PREVIOUS=new java.util.ArrayDeque<>(),GROUND_SPEAR_PREVIOUS=new java.util.ArrayDeque<>(),GROUND_MACE_PREVIOUS=new java.util.ArrayDeque<>(),AIR_TRIDENT_PREVIOUS=new java.util.ArrayDeque<>(),AIR_SPEAR_PREVIOUS=new java.util.ArrayDeque<>(),AIR_MACE_PREVIOUS=new java.util.ArrayDeque<>();
 @Inject(method="submit(Lcom/mojang/blaze3d/vertex/PoseStack;Lnet/minecraft/client/renderer/SubmitNodeCollector;III)V",at=@At("HEAD"))
 private void begin(PoseStack poses,SubmitNodeCollector collector,int light,int overlay,int outline,CallbackInfo ci){JUMP_PREVIOUS.push(dev.wildcraft.test.JumpAudit.submittingExpectedItem);dev.wildcraft.test.JumpAudit.submittingExpectedItem=dev.wildcraft.test.JumpAudit.enabled&&(Object)this==dev.wildcraft.test.JumpAudit.expectedItem;AIR_MACE_PREVIOUS.push(dev.wildcraft.test.AirMaceAudit.submittingExpectedItem);dev.wildcraft.test.AirMaceAudit.submittingExpectedItem=dev.wildcraft.test.AirMaceAudit.enabled&&(Object)this==dev.wildcraft.test.AirMaceAudit.expectedItem;AIR_SPEAR_PREVIOUS.push(dev.wildcraft.test.AirSpearAudit.submittingExpectedItem);dev.wildcraft.test.AirSpearAudit.submittingExpectedItem=dev.wildcraft.test.AirSpearAudit.enabled&&(Object)this==dev.wildcraft.test.AirSpearAudit.expectedItem;AIR_TRIDENT_PREVIOUS.push(dev.wildcraft.test.AirTridentAudit.submittingExpectedItem);dev.wildcraft.test.AirTridentAudit.submittingExpectedItem=dev.wildcraft.test.AirTridentAudit.enabled&&(Object)this==dev.wildcraft.test.AirTridentAudit.expectedItem;GROUND_MACE_PREVIOUS.push(dev.wildcraft.test.GroundMaceAudit.submittingExpectedItem);dev.wildcraft.test.GroundMaceAudit.submittingExpectedItem=dev.wildcraft.test.GroundMaceAudit.enabled&&(Object)this==dev.wildcraft.test.GroundMaceAudit.expectedItem;GROUND_SPEAR_PREVIOUS.push(dev.wildcraft.test.GroundSpearAudit.submittingExpectedItem);dev.wildcraft.test.GroundSpearAudit.submittingExpectedItem=dev.wildcraft.test.GroundSpearAudit.enabled&&(Object)this==dev.wildcraft.test.GroundSpearAudit.expectedItem;GROUND_TRIDENT_PREVIOUS.push(dev.wildcraft.test.GroundTridentAudit.submittingExpectedItem);dev.wildcraft.test.GroundTridentAudit.submittingExpectedItem=dev.wildcraft.test.GroundTridentAudit.enabled&&(Object)this==dev.wildcraft.test.GroundTridentAudit.expectedItem;CROSSBOW_PREVIOUS.push(dev.wildcraft.test.CrossbowTransitionAudit.submittingExpectedItem);dev.wildcraft.test.CrossbowTransitionAudit.submittingExpectedItem=dev.wildcraft.test.CrossbowTransitionAudit.enabled&&(Object)this==dev.wildcraft.test.CrossbowTransitionAudit.expectedItem;MACE_PREVIOUS.push(dev.wildcraft.test.MaceTransitionAudit.submittingExpectedItem);dev.wildcraft.test.MaceTransitionAudit.submittingExpectedItem=dev.wildcraft.test.MaceTransitionAudit.enabled&&(Object)this==dev.wildcraft.test.MaceTransitionAudit.expectedItem;SPEAR_PREVIOUS.push(dev.wildcraft.test.SpearTransitionAudit.submittingExpectedItem);dev.wildcraft.test.SpearTransitionAudit.submittingExpectedItem=dev.wildcraft.test.SpearTransitionAudit.enabled&&(Object)this==dev.wildcraft.test.SpearTransitionAudit.expectedItem;PREVIOUS.push(dev.wildcraft.test.TridentTransitionAudit.submittingExpectedItem);dev.wildcraft.test.TridentTransitionAudit.submittingExpectedItem=dev.wildcraft.test.TridentTransitionAudit.enabled&&(Object)this==dev.wildcraft.test.TridentTransitionAudit.expectedItem;}
 @Inject(method="submit(Lcom/mojang/blaze3d/vertex/PoseStack;Lnet/minecraft/client/renderer/SubmitNodeCollector;III)V",at=@At("RETURN"))
 private void end(PoseStack poses,SubmitNodeCollector collector,int light,int overlay,int outline,CallbackInfo ci){dev.wildcraft.test.JumpAudit.submittingExpectedItem=JUMP_PREVIOUS.pop();dev.wildcraft.test.AirMaceAudit.submittingExpectedItem=AIR_MACE_PREVIOUS.pop();dev.wildcraft.test.AirSpearAudit.submittingExpectedItem=AIR_SPEAR_PREVIOUS.pop();dev.wildcraft.test.AirTridentAudit.submittingExpectedItem=AIR_TRIDENT_PREVIOUS.pop();dev.wildcraft.test.GroundMaceAudit.submittingExpectedItem=GROUND_MACE_PREVIOUS.pop();dev.wildcraft.test.GroundSpearAudit.submittingExpectedItem=GROUND_SPEAR_PREVIOUS.pop();dev.wildcraft.test.GroundTridentAudit.submittingExpectedItem=GROUND_TRIDENT_PREVIOUS.pop();dev.wildcraft.test.CrossbowTransitionAudit.submittingExpectedItem=CROSSBOW_PREVIOUS.pop();dev.wildcraft.test.MaceTransitionAudit.submittingExpectedItem=MACE_PREVIOUS.pop();dev.wildcraft.test.SpearTransitionAudit.submittingExpectedItem=SPEAR_PREVIOUS.pop();dev.wildcraft.test.TridentTransitionAudit.submittingExpectedItem=PREVIOUS.pop();}
}
